-- Complete branded incident templates and editor-visible translations.
BEGIN;
INSERT INTO "email_template_translations" ("id", "emailTemplateId", "languageCode", "subject", "htmlContent", "updatedAt") VALUES
('default-incident-created-en', 'default-incident-created', 'en', 'New incident: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>New incident</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hello {{RECIPIENT_NAME}},</h2><p>A new simulation incident has been reported and is waiting for administrator review.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Incident number</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Simulation reference</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Current status</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Updated by</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Reported issue</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">View update</a></td></tr></table><p><br>Thank you,<br>The AXPO Team</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. All rights reserved.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-escalated-en', 'default-incident-escalated', 'en', 'Incident escalated: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Incident escalated</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hello {{RECIPIENT_NAME}},</h2><p>This incident has been escalated to the system administrators for technical review.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Incident number</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Simulation reference</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Previous status</td><td style="padding:10px 14px;word-break:break-word">{{PREVIOUS_STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Current status</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Updated by</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Reported issue</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Update notes</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{NOTES}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">View update</a></td></tr></table><p><br>Thank you,<br>The AXPO Team</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. All rights reserved.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-status-en', 'default-incident-status', 'en', 'Incident status updated: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Incident status updated</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hello {{RECIPIENT_NAME}},</h2><p>The status of this incident has changed. You can find the latest update below.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Incident number</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Simulation reference</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Previous status</td><td style="padding:10px 14px;word-break:break-word">{{PREVIOUS_STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Current status</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Updated by</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Reported issue</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Update notes</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{NOTES}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">View update</a></td></tr></table><p><br>Thank you,<br>The AXPO Team</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. All rights reserved.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-resolved-en', 'default-incident-resolved', 'en', 'Incident finalized: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Incident finalized</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hello {{RECIPIENT_NAME}},</h2><p>This incident has been finalized. Please find the resolution below.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Incident number</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Simulation reference</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Previous status</td><td style="padding:10px 14px;word-break:break-word">{{PREVIOUS_STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Current status</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Updated by</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Reported issue</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Resolution</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{RESOLUTION_NOTES}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">View update</a></td></tr></table><p><br>Thank you,<br>The AXPO Team</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. All rights reserved.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-created-es', 'default-incident-created', 'es', 'Nueva incidencia: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Nueva incidencia</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hola {{RECIPIENT_NAME}},</h2><p>Se ha reportado una nueva incidencia de simulación y está pendiente de revisión por los administradores.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Número de incidencia</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Referencia de simulación</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado actual</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Actualizado por</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Problema reportado</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">Ver actualización</a></td></tr></table><p><br>Gracias,<br>El equipo de AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos los derechos reservados.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-escalated-es', 'default-incident-escalated', 'es', 'Incidencia escalada: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Incidencia escalada</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hola {{RECIPIENT_NAME}},</h2><p>Esta incidencia se ha escalado a los administradores del sistema para su revisión técnica.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Número de incidencia</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Referencia de simulación</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado anterior</td><td style="padding:10px 14px;word-break:break-word">{{PREVIOUS_STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado actual</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Actualizado por</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Problema reportado</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Notas de la actualización</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{NOTES}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">Ver actualización</a></td></tr></table><p><br>Gracias,<br>El equipo de AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos los derechos reservados.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-status-es', 'default-incident-status', 'es', 'Estado de incidencia actualizado: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Estado de incidencia actualizado</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hola {{RECIPIENT_NAME}},</h2><p>El estado de esta incidencia ha cambiado. Encontrarás la última actualización a continuación.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Número de incidencia</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Referencia de simulación</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado anterior</td><td style="padding:10px 14px;word-break:break-word">{{PREVIOUS_STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado actual</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Actualizado por</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Problema reportado</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Notas de la actualización</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{NOTES}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">Ver actualización</a></td></tr></table><p><br>Gracias,<br>El equipo de AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos los derechos reservados.</td></tr></tbody></table>', CURRENT_TIMESTAMP),
('default-incident-resolved-es', 'default-incident-resolved', 'es', 'Incidencia finalizada: #{{INCIDENT_NUMBER}}', '<meta charset="UTF-8"><title>Incidencia finalizada</title><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse;font-family:Arial,sans-serif"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150" style="max-width:150px;height:auto;border:0"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6;font-size:14px"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hola {{RECIPIENT_NAME}},</h2><p>Esta incidencia se ha finalizado. A continuación encontrarás la resolución.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Número de incidencia</td><td style="padding:10px 14px;word-break:break-word">#{{INCIDENT_NUMBER}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Referencia de simulación</td><td style="padding:10px 14px;word-break:break-word">{{SIMULATION_REFERENCE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado anterior</td><td style="padding:10px 14px;word-break:break-word">{{PREVIOUS_STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Estado actual</td><td style="padding:10px 14px;word-break:break-word">{{STATUS}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;vertical-align:top">Actualizado por</td><td style="padding:10px 14px;word-break:break-word">{{CHANGED_BY}}</td></tr></table><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Problema reportado</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{DESCRIPTION}}</p><h3 style="font-size:15px;margin:24px 0 8px;color:#2d2d2d">Resolución</h3><p style="margin:0;white-space:pre-wrap;word-break:break-word">{{RESOLUTION_NOTES}}</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0"><tr><td style="background-color:#ff2850;border-radius:6px;text-align:center"><a href="{{ISSUE_URL}}" style="display:inline-block;padding:12px 24px;color:#ffffff;text-decoration:none;font-weight:bold">Ver actualización</a></td></tr></table><p><br>Gracias,<br>El equipo de AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos los derechos reservados.</td></tr></tbody></table>', CURRENT_TIMESTAMP)
ON CONFLICT ("emailTemplateId", "languageCode") DO UPDATE
SET "subject" = EXCLUDED."subject", "htmlContent" = EXCLUDED."htmlContent", "updatedAt" = CURRENT_TIMESTAMP;

UPDATE "email_templates" template
SET "subject" = translation."subject", "htmlContent" = translation."htmlContent", "updatedAt" = CURRENT_TIMESTAMP
FROM "email_template_translations" translation
WHERE translation."emailTemplateId" = template."id" AND translation."languageCode" = 'en'
AND template."id" IN ('default-incident-created', 'default-incident-escalated', 'default-incident-status', 'default-incident-resolved');
COMMIT;
